<?php
/**
 * MCP server for CodeQuest — dependency-free stdio JSON-RPC 2.0.
 *
 * Auto-generated by the TRL/MCP rollout. Implements the Model Context Protocol
 * `tools` capability over stdio. Configuration lives in mcp-server/server_config.json.
 *
 * Run:  php mcp-server/server.php
 */

declare(strict_types=1);

$HERE = __DIR__;
$REPO_ROOT = dirname($HERE);
$SERVER_NAME = "CodeQuest-mcp";
$SERVER_VERSION = "1.0.0";
$PROTOCOL_VERSION = "2024-11-05";

$CONFIG = json_decode(file_get_contents($HERE . "/server_config.json"), true) ?: [];
$APP = $CONFIG["app"] ?? [];
$ROUTES = $CONFIG["routes"] ?? [];
$SCRIPTS = $CONFIG["scripts"] ?? [];
$PAGES = $CONFIG["pages"] ?? [];
$BASE_URL = getenv("MCP_APP_BASE_URL") ?: ($CONFIG["base_url"] ?? "http://localhost:8000");

function schema(array $properties = [], array $required = []): array {
    return ["type" => "object", "properties" => (object) $properties, "required" => $required, "additionalProperties" => false];
}
function strprop(string $d): array { return ["type" => "string", "description" => $d]; }

function app_info(): string {
    global $APP, $ROUTES, $SCRIPTS, $SERVER_NAME, $SERVER_VERSION, $REPO_ROOT;
    return json_encode([
        "name" => $APP["name"] ?? $SERVER_NAME,
        "version" => $APP["version"] ?? "unknown",
        "description" => $APP["description"] ?? "",
        "repo_root" => $REPO_ROOT,
        "scripts" => array_keys($SCRIPTS),
        "routes" => array_map(fn($r) => strtoupper($r["method"]) . " " . $r["path"], $ROUTES),
        "mcp_server" => ["name" => $SERVER_NAME, "version" => $SERVER_VERSION, "protocol" => $PROTOCOL_VERSION],
    ], JSON_PRETTY_PRINT);
}

function run_script(array $args): string {
    global $SCRIPTS, $REPO_ROOT;
    $name = (string) ($args["name"] ?? "");
    if (!isset($SCRIPTS[$name])) {
        throw new Exception("unknown script: $name");
    }
    $extra = array_map("strval", $args["args"] ?? []);
    $cmd = "cd " . escapeshellarg($REPO_ROOT) . " && " . $SCRIPTS[$name] . " " . implode(" ", array_map("escapeshellarg", $extra)) . " 2>&1";
    return trim((string) shell_exec($cmd)) ?: "(no output)";
}

function route_call(array $route, array $args): string {
    global $BASE_URL;
    $url = rtrim($BASE_URL, "/") . $route["path"];
    foreach (explode("/", $route["path"]) as $part) {
        if (str_starts_with($part, "{") && str_ends_with($part, "}")) {
            $key = substr($part, 1, -1);
            $url = str_replace($part, rawurlencode((string) ($args[$key] ?? "")), $url);
        }
    }
    if (!empty($args["query"]) && is_array($args["query"])) {
        $url .= (str_contains($url, "?") ? "&" : "?") . http_build_query($args["query"]);
    }
    $method = strtoupper($route["method"]);
    $ch = curl_init($url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_CUSTOMREQUEST, $method);
    curl_setopt($ch, CURLOPT_TIMEOUT, 180);
    if (in_array($method, ["POST", "PUT", "PATCH"], true) && array_key_exists("body", $args)) {
        curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($args["body"]));
        curl_setopt($ch, CURLOPT_HTTPHEADER, ["Content-Type: application/json"]);
    }
    $resp = curl_exec($ch);
    if ($resp === false) {
        return "cURL error: " . curl_error($ch);
    }
    $code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
    curl_close($ch);
    return $code >= 400 ? "HTTP $code: $resp" : (string) $resp;
}

function list_pages(): string {
    global $PAGES;
    $p = $PAGES;
    sort($p);
    return json_encode($p, JSON_PRETTY_PRINT);
}
function get_page(array $args): string {
    global $PAGES, $REPO_ROOT;
    $name = (string) ($args["page"] ?? "");
    $match = null;
    foreach ($PAGES as $p) {
        if ($p === $name || strtolower($p) === strtolower($name)) { $match = $p; break; }
    }
    if ($match === null) { throw new Exception("unknown page: $name"); }
    return (string) file_get_contents($REPO_ROOT . "/" . $match);
}
function search_content(array $args): string {
    global $PAGES, $REPO_ROOT;
    $needle = strtolower((string) ($args["query"] ?? ""));
    if ($needle === "") { throw new Exception("query is required"); }
    $hits = [];
    foreach ($PAGES as $p) {
        $text = @file_get_contents($REPO_ROOT . "/" . $p);
        if ($text === false) { continue; }
        foreach (explode("\n", $text) as $i => $line) {
            if (str_contains(strtolower($line), $needle)) {
                $hits[] = $p . ":" . ($i + 1) . ": " . substr(trim($line), 0, 200);
            }
        }
    }
    return $hits ? implode("\n", array_slice($hits, 0, 200)) : "(no matches)";
}

function build_tools(): array {
    $tools = [
        "app_info" => ["description" => "Metadata about this application and its MCP server.", "inputSchema" => schema(), "call" => "app_info"],
    ];
    if (count($GLOBALS["SCRIPTS"]) > 0) {
        $tools["list_scripts"] = ["description" => "List composer scripts.", "inputSchema" => schema(), "call" => fn($a) => json_encode($GLOBALS["SCRIPTS"], JSON_PRETTY_PRINT)];
        $tools["run_script"] = [
            "description" => "Run a composer script. `args` is an array of extra arguments.",
            "inputSchema" => schema(["name" => strprop("Script name."), "args" => ["type" => "array", "items" => ["type" => "string"]]], ["name"]),
            "call" => "run_script",
        ];
    }
    foreach ($GLOBALS["ROUTES"] as $route) {
        $safe = strtolower(trim(preg_replace("/[^a-zA-Z0-9]+/", "_", $route["method"] . "_" . $route["path"]), "_"));
        $params = [];
        $required = [];
        foreach (explode("/", $route["path"]) as $part) {
            if (str_starts_with($part, "{") && str_ends_with($part, "}")) {
                $key = substr($part, 1, -1);
                $params[$key] = strprop("Path parameter `$key`.");
                $required[] = $key;
            }
        }
        if (in_array(strtoupper($route["method"]), ["POST", "PUT", "PATCH"], true)) {
            $params["body"] = ["type" => "object", "description" => "JSON request body."];
        }
        $params["query"] = ["type" => "object", "description" => "Query string parameters."];
        $r = $route;
        $tools["http_" . $safe] = [
            "description" => strtoupper($route["method"]) . " " . $route["path"],
            "inputSchema" => schema($params, $required),
            "call" => fn($a) => route_call($r, $a),
        ];
    }
    if (count($GLOBALS["PAGES"]) > 0) {
        $tools["list_pages"] = ["description" => "List the site's HTML pages.", "inputSchema" => schema(), "call" => fn($a) => list_pages()];
        $tools["get_page"] = ["description" => "Return a page's HTML source.", "inputSchema" => schema(["page" => strprop("Page path.")], ["page"]), "call" => "get_page"];
        $tools["search_content"] = ["description" => "Search across site pages for a string.", "inputSchema" => schema(["query" => strprop("Text to find.")], ["query"]), "call" => "search_content"];
    }
    return $tools;
}

$TOOLS = build_tools();

function handle(array $request): ?array {
    global $TOOLS, $SERVER_NAME, $SERVER_VERSION, $PROTOCOL_VERSION;
    $method = $request["method"] ?? null;
    $id = $request["id"] ?? null;
    if ($method === "initialize") {
        return ["jsonrpc" => "2.0", "id" => $id, "result" => [
            "protocolVersion" => $PROTOCOL_VERSION,
            "capabilities" => ["tools" => ["listChanged" => false]],
            "serverInfo" => ["name" => $SERVER_NAME, "version" => $SERVER_VERSION],
        ]];
    }
    if (in_array($method, ["notifications/initialized", "initialized", "notifications/cancelled"], true)) {
        return null;
    }
    if ($method === "ping") { return ["jsonrpc" => "2.0", "id" => $id, "result" => (object) []]; }
    if ($method === "tools/list") {
        $out = [];
        foreach ($TOOLS as $name => $t) {
            $out[] = ["name" => $name, "description" => $t["description"], "inputSchema" => $t["inputSchema"]];
        }
        return ["jsonrpc" => "2.0", "id" => $id, "result" => ["tools" => $out]];
    }
    if ($method === "tools/call") {
        $params = $request["params"] ?? [];
        $name = $params["name"] ?? "";
        $args = $params["arguments"] ?? [];
        if (!isset($TOOLS[$name])) {
            return ["jsonrpc" => "2.0", "id" => $id, "result" => ["content" => [["type" => "text", "text" => "Unknown tool: $name"]], "isError" => true]];
        }
        try {
            $text = ($TOOLS[$name]["call"])($args);
            return ["jsonrpc" => "2.0", "id" => $id, "result" => ["content" => [["type" => "text", "text" => (string) $text]], "isError" => false]];
        } catch (Throwable $e) {
            return ["jsonrpc" => "2.0", "id" => $id, "result" => ["content" => [["type" => "text", "text" => get_class($e) . ": " . $e->getMessage()]], "isError" => true]];
        }
    }
    if (in_array($method, ["resources/list", "prompts/list"], true)) {
        $key = $method === "resources/list" ? "resources" : "prompts";
        return ["jsonrpc" => "2.0", "id" => $id, "result" => [$key => []]];
    }
    if ($id === null) { return null; }
    return ["jsonrpc" => "2.0", "id" => $id, "error" => ["code" => -32601, "message" => "Method not found: $method"]];
}

while (($line = fgets(STDIN)) !== false) {
    $line = trim($line);
    if ($line === "") { continue; }
    $request = json_decode($line, true);
    if (!is_array($request)) {
        echo json_encode(["jsonrpc" => "2.0", "id" => null, "error" => ["code" => -32700, "message" => "Parse error"]]) . "\n";
        continue;
    }
    $response = handle($request);
    if ($response !== null) {
        echo json_encode($response) . "\n";
    }
}
